#!/usr/bin/env python3
"""Extract all 256 CP437 glyphs from a raw 8x16 VGA console font into src/font.rs."""
import gzip
import sys

SRC = "/usr/share/kbd/consolefonts/alt-8x16.gz"
OUT = "src/font.rs"


def main() -> int:
    try:
        data = gzip.open(SRC, "rb").read()
    except OSError:
        print(f"cannot read {SRC}", file=sys.stderr)
        return 1
    if len(data) < 256 * 16:
        print("not a raw 8x16 font", file=sys.stderr)
        return 1

    lines = [
        "// Generated by tools/mkfont.py from alt-8x16 (raw VGA font).",
        "// Each glyph is 16 rows, MSB = leftmost pixel. Full CP437 256 glyphs.",
        "",
        "pub static FONT: [[u8; 16]; 256] = [",
    ]
    for ch in range(256):
        o = ch * 16
        glyph = data[o : o + 16]
        body = ", ".join(f"0x{b:02x}" for b in glyph)
        lines.append(f"    [{body}], // 0x{ch:02x}")
    lines.append("];")
    lines.append("")
    lines.append("#[inline]")
    lines.append("pub fn glyph(ch: u8) -> &'static [u8; 16] {")
    lines.append("    &FONT[ch as usize]")
    lines.append("}")
    lines.append("")
    with open(OUT, "w") as f:
        f.write("\n".join(lines))
    print(f"wrote {OUT}: 256 glyphs")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
